window.syncDiskPacks = async function() {
  if (window.sakura && window.sakura.listInstances) {
    try {
      const diskList = await window.sakura.listInstances();
      const diskIds = new Set(diskList.map(dp => dp.id));
      let changed = false;

      // Add or update from disk
      diskList.forEach(dp => {
        const existing = ST.packs.find(p => p.id === dp.id);
        if (!existing) {
          ST.packs.push(dp);
          changed = true;
        } else {
          // Sync mod count and metadata from disk if present
          if (dp.mods && Array.isArray(dp.mods)) {
            // merge disk mods into pack mods
            const knownNames = new Set(existing.mods.map(m => m.t.toLowerCase()));
            dp.mods.forEach(dm => {
              if (!knownNames.has(dm.t.toLowerCase())) {
                existing.mods.push(dm);
                changed = true;
              }
            });
          }
        }
      });

      // Remove packs from ST.packs that were deleted from disk (except FEAT templates f1..f4)
      const prevLen = ST.packs.length;
      ST.packs = ST.packs.filter(p => diskIds.has(p.id) || (p.id && p.id.startsWith('f') && p.id.length <= 4));
      if (ST.packs.length !== prevLen) {
        changed = true;
      }

      if (changed) {
        save();
        if (window.renderPackSel) window.renderPackSel();
        if (mtab === 'mine') {
          $('#mc').textContent=ST.packs.length?`Мои сборки: ${ST.packs.length}`:'';
          $('#ml').innerHTML=`<div style="grid-column:1/-1;display:flex;gap:8px;flex-wrap:wrap"><button class="btn on" data-pa="new">Новая сборка</button><button class="btn" data-pa="imp">Импорт из файла</button></div>`+ST.packs.map(p=>pcard(p,1)).join('');
        }
      }
    } catch(e) {
      console.warn("Could not sync disk packs:", e);
    }
  }
};
