async function saveBlob(blob,name){
  try{const d=null;if(d){await d.save({filename:name,data:blob});return}}catch(e){if(e&&e.code==='declined')return}
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);
}
/* downloading one mod with its required libraries */
async function resolveMr(ref){
  if(ref.id&&ref.src!=='demo')return ref.id;
  const r=await mj(`/search?query=${encodeURIComponent(ref.t)}&facets=${encodeURIComponent(JSON.stringify([['project_type:mod']]))}&limit=1`);
  if(!r.hits.length)throw new Error('none');ref.id=r.hits[0].project_id;ref.src='mr';return ref.id;
}
async function saveModFile(url, filename, packId){
  if(packId && window.sakura && window.sakura.downloadModToPack){
    await window.sakura.downloadModToPack(packId, url, filename);
  }else{
    const r=await fetch(url);if(!r.ok)throw new Error('file');
    await saveBlob(await r.blob(), filename);
  }
}
async function getMod(ref,v,l,only,seen,got,packId){
  const key=ref.src+':'+(ref.id||ref.t);if(seen.has(key))return;seen.add(key);
  if(ref.src==='cf'){
    const f=(await cfj(`/mods/${encodeURIComponent(ref.id)}/files?gameVersion=${encodeURIComponent(v)}&modLoaderType=${CFL[l]}&pageSize=1`)).data[0];
    if(!f)throw new Error('none');
    const url=f.downloadUrl||(await cfj(`/mods/${encodeURIComponent(ref.id)}/files/${f.id}/download-url`)).data;
    await saveModFile(url, f.fileName, packId);got.push(f.fileName);
    if(!only)for(const d of f.dependencies||[])if(d.relationType===3)try{await getMod({id:String(d.modId),t:'',src:'cf'},v,l,false,seen,got,packId)}catch(x){}
    return;
  }
  const pid=await resolveMr(ref);
  let vers=[];
  try{vers=await mj(`/project/${encodeURIComponent(pid)}/version?loaders=${encodeURIComponent(JSON.stringify([LK[l]]))}&game_versions=${encodeURIComponent(JSON.stringify([v]))}`);}catch(x){}
  if(!vers||!vers.length){
    try{vers=await mj(`/project/${encodeURIComponent(pid)}/version?loaders=${encodeURIComponent(JSON.stringify([LK[l]]))}`);}catch(x){}
  }
  const ver=vers&&vers[0];if(!ver)throw new Error('none');
  const f=ver.files.find(x=>x.primary)||ver.files[0];
  await saveModFile(f.url, f.filename, packId);got.push(f.filename);
  if(only)return;
  for(const d of ver.dependencies||[]){
    if(d.dependency_type!=='required')continue;
    let id=d.project_id;
    if(!id&&d.version_id){try{id=(await mj('/version/'+d.version_id)).project_id}catch(x){}}
    if(id)try{await getMod({id,t:'',src:'mr'},v,l,false,seen,got,packId)}catch(x){}
  }
}
async function dlOne(b){
  if(b.dataset.src==='demo'){toast('Демо: в браузере или приложении файл скачается сразу в «Загрузки», без перехода на сайт');return}
  const v=mv.value,t=b.dataset.t,only=!!b.dataset.only||b.dataset.pt==='modpack',got=[];
  b.disabled=true;toast(`Скачиваем ${t}…`);
  try{
    await getMod({id:b.dataset.id,t,src:b.dataset.src},v,mld,only,new Set(),got);
    mi[t]=[v+' '+mld];ST.mods.unshift({t,v,l:mld,d:Date.now()});ST.mods=ST.mods.slice(0,200);save();
    toast(got.length>1?`${t} скачан вместе с нужными библиотеками (${got.length} файла) в «Загрузки»`:`${t} скачан в «Загрузки»`);
  }catch(err){toast(err.message==='none'?`Для ${v} и ${mld} у «${t}» нет подходящего файла`:'Не удалось скачать. Проверьте сеть и повторите.')}
  finally{b.disabled=false}
}
async function dlPack(p,b){
  if(!p.mods.length){toast('В сборке пока нет модов');return}
  b.disabled=true;const seen=new Set(),got=[];let bad=0;
  for(let i=0;i<p.mods.length;i++){
    toast(`Скачиваем «${p.name}»: ${i+1} из ${p.mods.length}`);
    try{await getMod({...p.mods[i]},p.v,p.l,false,seen,got,p.id)}catch(e){bad++;if(e.message==='Failed to fetch'&&!got.length){toast('Нет доступа к сети. Откройте лаунчер в браузере или приложении.');b.disabled=false;return}}
  }
  b.disabled=false;toast(`Сборка «${p.name}»: скачано файлов ${got.length}`+(bad?`, не нашлось для ${p.v} ${p.l}: ${bad}`:''));
}
/* dialogs */
const pkd=$('#pkd'),pkn=$('#pkn');let addRef=null;
function newPack(after){
  $('#pnn').value='';$('#pnd').value='';
  if($('#mv')&&$('#pnv'))$('#pnv').innerHTML=$('#mv').innerHTML;
  if($('#pnl'))$('#pnl').innerHTML=LD.map(l=>`<option value="${l}">${l}</option>`).join('');
  $('#pnv').value=mv.value;$('#pnl').value=mld;$('#pne').textContent='';pkn._after=after||null;pkn.showModal();$('#pnn').focus();
}
$('#pnc').onclick=()=>pkn.close();
$('#pnok').onclick=()=>{
  const n=$('#pnn').value.trim(),d=$('#pnd').value.trim();
  if(n.length<2){$('#pne').textContent='Введите название сборки.';return}
  
  let baseId = makePackId(n);
  let finalId = baseId;
  let counter = 1;
  while (ST.packs.some(p => p.id === finalId)) {
    finalId = `${baseId}_${counter++}`;
  }

  const pk={id:finalId,name:n,desc:d,v:$('#pnv').value,l:$('#pnl').value,mods:[],pub:false,ts:Date.now(),createdOnDisk:true};
  ST.packs.unshift(pk);
  save();
  if (window.sakura && window.sakura.createInstance) {
    window.sakura.createInstance({ id: finalId, name: n, desc: d, v: pk.v, l: pk.l });
  }
  pkn.close();
  const a=pkn._after;pkn._after=null;if(a)a(pk);
  if(mtab==='mine')rMine();
  if(window.renderPackSel)window.renderPackSel();
  toast(`Сборка «${n}» создана`);
};
function addToPack(ref){
  addRef=ref;$('#pkm').textContent=`Мод: ${ref.t}`;
  $('#pks').innerHTML=ST.packs.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} (${esc(p.v)}, ${esc(p.l)})</option>`).join('')+'<option value="_new">Новая сборка…</option>';
  $('#pks').value=ST.packs.length?ST.packs[0].id:'_new';pkd.showModal();
}
$('#pkc').onclick=()=>pkd.close();
$('#pko').onclick=()=>{
  const id=$('#pks').value;pkd.close();
  const put=async pk=>{
    if(pk.mods.some(m=>m.src===addRef.src&&m.id===addRef.id&&m.t===addRef.t)){toast('Этот мод уже есть в сборке');return}
    pk.mods.push(addRef);save();toast(`«${addRef.t}» добавлен в сборку «${pk.name}». Загрузка файла…`);
    try {
      await getMod({...addRef}, pk.v, pk.l, false, new Set(), [], pk.id);
      toast(`Файл «${addRef.t}» сохранён в сборку!`);
    }catch(err){console.warn('Could not auto-download mod:', err)}
  };
  if(id==='_new')newPack(put);else{const pk=ST.packs.find(p=>p.id===id);if(pk)put(pk)}
};
/* pack actions */
async function publishPack(p){
  if(p.desc.trim().length<10){toast('Добавьте описание: что в сборке и для чего она');return}
  if(!p.mods.length){toast('В сборке пока нет модов');return}
  if(DB&&UID){
    try{await DB.doc('packs/'+p.id).set({id:p.id,name:p.name,desc:p.desc,v:p.v,l:p.l,mods:p.mods,author:ST.nick||'Игрок',owner:UID,ts:Date.now()});p.pub=true;save();toast('Сборка опубликована в сообществе');rMine();return}catch(e){}
  }
  expPack(p);toast('Публикация онлайн станет доступна с сервером Sakura. Файл сборки сохранён: отправьте его друзьям, они импортируют его');
}
function expPack(p){saveBlob(new Blob([JSON.stringify({sakurapack:1,name:p.name,desc:p.desc,v:p.v,l:p.l,mods:p.mods},null,1)],{type:'application/json'}),p.name.replace(/[^\w\-]+/g,'_')+'.sakurapack.json')}
window.expPack = expPack;
$('#pimp').onchange=async e=>{
  const f=e.target.files[0];e.target.value='';if(!f)return;
  try{
    const j=JSON.parse(await f.text());
    if(!j||!j.name||!Array.isArray(j.mods))throw new Error('bad');
    const pk={id:newId(),name:String(j.name).slice(0,48),desc:String(j.desc||'').slice(0,600)||'Без описания',v:VL.includes(j.v)?j.v:'1.21.1',l:LD.includes(j.l)?j.l:'Fabric',pub:false,ts:Date.now(),
      mods:j.mods.slice(0,300).filter(m=>m&&m.t).map(m=>({id:String(m.id||'').slice(0,40),t:String(m.t).slice(0,80),src:['mr','cf','demo'].includes(m.src)?m.src:'mr'}))};
    ST.packs.unshift(pk);save();if(mtab==='mine')rMine();toast(`Сборка «${pk.name}» импортирована`);
  }catch(x){toast('Не удалось прочитать файл сборки')}
};
$('#ml').onclick=async e=>{
  const pa=e.target.closest('[data-pa]');
  if(pa){
    const a=pa.dataset.pa,p=PK[pa.dataset.pid];
    if(a==='new'){ newPack(); return; }
    if(a==='imp'){ 
      const inp = $('#pimp');
      if (inp) inp.click();
      return; 
    }
    if(a==='dl'&&p)dlPack(p,pa);
    else if(a==='share'&&p)publishPack(p);
    else if(a==='exp'&&p)expPack(p);
    else if(a==='unpub'&&p){try{if(DB)await DB.doc('packs/'+p.id).delete()}catch(x){}p.pub=false;save();rMine();toast('Сборка снята с публикации')}
    else if(a==='del'&&p){if(confirm('Удалить сборку?')){ST.packs=ST.packs.filter(q=>q.id!==p.id);save();rMine();toast('Сборка удалена')}}
    else if(a==='rm'&&p){p.mods.splice(+pa.dataset.i,1);save();rMine()}
    else if(a==='copy'&&p){const c={...p,id:newId(),pub:false,author:undefined,mods:p.mods.map(m=>({...m})),ts:Date.now()};ST.packs.unshift(c);save();toast(`«${p.name}» добавлена в ваши сборки`)}
    return;
  }

  const pkItem = e.target.closest('.pk');
  if (pkItem && !e.target.closest('button')) {
    const pid = pkItem.dataset.pid || pkItem.querySelector('[data-pid]')?.dataset.pid;
    if (pid) window.openModpackDialog(pid);
    return;
  }
  const x=e.target.closest('[data-x]');

  if(x){const mx=x.closest('.mc2').querySelector('.mx');mx.hidden=!mx.hidden;x.setAttribute('aria-expanded',String(!mx.hidden));return}
  const r=e.target.closest('[data-rm]');
  if(r){ST.mods.splice(+r.dataset.rm,1);save();minst();return}
  const ad=e.target.closest('[data-add]');
  if(ad){const d=ad.closest('.mc2').querySelector('.dlb');addToPack({id:d.dataset.id,t:d.dataset.t,src:d.dataset.src});return}
  
    const b=e.target.closest('[data-id]');
    if(b&&!b.disabled) {
      if (b.dataset.pt === 'mod') {
        addToPack({id:b.dataset.id,t:b.dataset.t,src:b.dataset.src});
      } else {
        dlOne(b);
      }
    }
  
};

